const app=document.querySelector('#app');
const products=[{id:'sandwich',label:'Traditional sandwich',unit:'sandwich',price:8,description:'A satisfying sandwich with crisp greens and a generous filling. Ask the team about available options.'},{id:'wrap',label:'Lavash wrap',unit:'wrap',price:8.50,description:'Colourful vegetables wrapped up for a fresh, easy lunch. Choose your quantities and make it part of the mix.'},{id:'salad',label:'Seasonal salad box',unit:'box',price:16,description:'A colourful salad for a lighter lunch. Speak with the team about ingredients and dietary requirements.'}];
const statuses=['New','Needs clarification','Awaiting availability review','Ready for staff quote','Closed'];
const money=v=>'A'+new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:2,minimumFractionDigits:2}).format(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function futureDate(){let d=new Date();d.setDate(d.getDate()+14);return new Intl.DateTimeFormat('en-CA',{timeZone:'Australia/Sydney',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
const seedDate=()=>new Date('2026-11-05T12:15:00+11:00')>new Date()?'2026-11-05':futureDate();
let draft,requests,selected='REQ-001',filter='All',busy=false,result=null,qtyErrors={},simulationRun=0;
function reset(){simulationRun++;draft={qty:{sandwich:12,wrap:0,salad:4},date:seedDate(),time:'12:15',headcount:'16',company:'Office lunch',name:'Event organiser',email:'organiser@example.com',phone:'',street:'Delivery address to be confirmed',suburb:'Newcastle',postcode:'2300',categories:[],note:'',ack:false};requests=[{id:'REQ-001',...structuredClone(draft),status:'New',missing:[],history:[],staffNote:''},{id:'REQ-002',...structuredClone(draft),company:'Studio lunch',qty:{sandwich:0,wrap:8,salad:0},headcount:'8',street:'',status:'Needs clarification',missing:['Street address'],history:[],staffNote:''},{id:'REQ-003',...structuredClone(draft),company:'Workshop lunch',qty:{sandwich:6,wrap:0,salad:6},headcount:'12',categories:['Vegetarian discussion'],note:'Discuss menu suitability with the organiser.',status:'Awaiting availability review',missing:[],history:[],staffNote:''}];selected='REQ-001';filter='All';result=null;busy=false;qtyErrors={};draft={...draft,qty:{sandwich:0,wrap:0,salad:0},headcount:'',company:'',name:'',email:'',street:'',suburb:'',postcode:''}}
reset();
function totals(q=draft.qty){return {count:products.reduce((s,p)=>s+Number(q[p.id]||0),0),sum:products.reduce((s,p)=>s+Number(q[p.id]||0)*p.price,0)}}
function art(type='all'){let file=type==='all'?'spread':type==='sandwich'?'toasted-sandwich':type;return `<img class="foodphoto" src="/images/${file}.jpg" alt="Food photography: ${type==='all'?'a colourful food spread':type==='sandwich'?'a sandwich with greens':type==='wrap'?'filled tortilla wraps':'a colourful salad'}" loading="${type==='all'?'eager':'lazy'}" width="1200" height="900">`}
function menu(){return menuDirectory()}
function crumbs(step){return `<div class="breadcrumbs" aria-label="Request steps">${[['lunch','01 Menu'],['request','02 Details'],['review','03 Review']].map(([r,l])=>`<a href="/${r}" data-route class="${step===r?'active':''}" ${step===r?'aria-current="step"':''}>${l}</a>`).join('')}</div>`}
function summary(q=draft.qty,action=''){let t=totals(q);return `<aside class="summary"><div class="tinytitle">YOUR LUNCH REQUEST</div><h3 style="margin-top:12px">Lunch, at a glance.</h3>${t.count?products.filter(p=>q[p.id]>0).map(p=>`<div class="summaryline"><span>${q[p.id]} × ${p.label}</span><span>${money(q[p.id]*p.price)}</span></div>`).join(''):'<p class="micro">Your basket is empty. Add an item to begin.</p>'}<div class="summaryline total"><span>Subtotal</span><span>${money(t.sum)}</span></div><p class="micro">${t.count} items · Menu subtotal.<br>Delivery, taxes and any additional charges are subject to confirmation.</p>${action}<p class="micro" style="margin:17px 0 0">Availability, dietary suitability and final price require staff review.</p></aside>`}
function landing(){return `<div class="foodhome"><section class="foodhero"><div class="hero-backdrop"><img src="/images/toasted-sandwich.jpg" width="2000" height="1333" fetchpriority="high" alt="Golden toasted sandwiches layered with crisp lettuce and tomato"></div><div class="hero-shade"></div><div class="foodhero-content"><div class="eyebrow">FEAST CATERING · NEWCASTLE & THE HUNTER</div><h1>Good food.<br>Great<br><em>gatherings.</em></h1><p>From a boardroom lunch to a wedding celebration. Bring your people together with Feast Catering.</p><div class="heroactions"><a class="btn food-orange" href="/menu" data-route>Find your perfect feast </a><a class="hero-scroll" href="/#food-menu" data-food-scroll>Take a look </a></div></div><div class="food-orbit" aria-hidden="true"><span>GOOD FOOD<br>GOOD COMPANY</span><b><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></b></div><a class="hero-freshcard" href="/menu" data-route><img src="/images/salad.jpg" width="450" height="350" alt="A colourful bowl of vegetables and grains"><div><span>ON THE LIGHTER SIDE</span><strong>A little fresh thinking.</strong><small>Explore the salad box </small></div></a><div class="hero-bottomline"><span>WEDDINGS. CELEBRATIONS. CORPORATE EVENTS. EVERYDAY GATHERINGS.</span><span>SCROLL FOR SOMETHING GOOD </span></div></section><section class="foodticker" aria-label="Sandwiches, wraps and salad boxes"><div class="ticker-track">${[0,1].map(i=>`<div ${i?'aria-hidden="true"':''}><span>GOOD FOOD</span><b><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></b><span>GREAT COMPANY</span><b><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></b><span>FRESH PERSPECTIVES</span><b><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></b><span>BETTER LUNCH BREAKS</span><b><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></b></div>`).join('')}</div></section>${lunchSpotlight()}${wowSections()}<section id="food-menu" class="food-menu feast-home-menus"><div class="food-container"><div class="sectionhead reveal"><div><div class="eyebrow">SEVEN MENUS. SO MANY OCCASIONS.</div><h2>There's a feast<br><em>for that.</em></h2></div><div><p>Breakfasts, working lunches, canapés and shared dinners. Pick a menu for the way you want to gather.</p><a class="quietlink" href="/menu" data-route>Explore all seven menus </a></div></div><div class="home-collection-grid">${[collectionData[0],collectionData[1],collectionData[3],collectionData[5]].map(menuTile).join('')}</div><div class="home-all-menus">${collectionData.map(c=>`<a href="/menus/${c.id}" data-route>${c.short} </a>`).join('')}</div></div></section>${servicesSection()}<section class="sharing-banner"><img src="/images/platter.jpg" alt="A generous platter of sandwiches filled with greens, tomatoes and cheese" loading="lazy" width="1800" height="1200"><div class="sharing-overlay"></div><div class="sharing-copy reveal"><div class="eyebrow">SOME THINGS ARE BETTER TOGETHER</div><h2>Pass it round.<br><em>Make their day.</em></h2><p>From the first bite to the last conversation.<br>Bring something good to your next gathering.</p><a class="btn food-orange" href="/menu" data-route>Find a menu to share </a></div><div class="sharing-side" aria-hidden="true">MADE FOR SHARING</div></section>${filmSection()}<section class="food-story"><div class="food-container food-story-grid"><div class="story-collage reveal"><div class="collage-main"><img src="/images/salad.jpg" alt="Fresh vegetables surrounding a colourful grain and salad bowl" loading="lazy" width="1400" height="1000"></div><div class="collage-small"><img src="/images/wrap.jpg" alt="Freshly prepared tortilla wraps" loading="lazy" width="900" height="900"></div><span class="collage-note">a little colour,<br>a lot of flavour.</span><span class="collage-dish" aria-hidden="true"><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></span></div><div class="story-copy reveal"><div class="eyebrow">GOOD FOOD. NO OVERTHINKING.</div><h2>More flavour.<br><em>Less fuss.</em></h2><p>Tracy Roddenby and her team cater for gatherings across Newcastle, the Hunter region and beyond. From a family table to a large celebration, start with the people and the occasion.</p><div class="story-points"><div><span>01</span><p><strong>Pick your perfect mix.</strong>Choose your food and quantities.</p></div><div><span>02</span><p><strong>Tell us about the occasion.</strong>Add your date, delivery and dietary notes.</p></div><div><span>03</span><p><strong>Bring the details together.</strong>Prepare your request for team review.</p></div></div><a class="btn" href="/about" data-route>Meet Feast Catering </a></div></div></section><section id="how" class="food-how"><div class="food-container"><div class="food-how-top reveal"><div class="eyebrow">FROM THE MENU TO YOUR MEETING</div><h2>A good lunch starts<br>with <em>a little planning.</em></h2></div><div class="food-how-grid"><div class="reveal"><span>01 / THE FOOD</span><h3>Something to<br>look forward to.</h3><p>Find your favourites and set the quantities. Keep an eye on your menu subtotal as you go.</p></div><div class="reveal"><span>02 / THE DETAILS</span><h3>A place. A time.<br>A hungry team.</h3><p>Add your event, delivery address and any dietary questions the catering team should discuss.</p></div><div class="reveal"><span>03 / THE REVIEW</span><h3>All together.<br>Ready for a look.</h3><p>Prepare a clear lunch brief. Availability, dietary suitability and final pricing need team approval.</p></div></div></div></section><section class="food-final"><div class="food-final-left"><img src="/images/spread.jpg" alt="Colourful food with fresh garnishes and sauces" loading="lazy" width="900" height="900"></div><div class="food-final-copy reveal"><div class="eyebrow">YOUR NEXT OCCASION IS CALLING</div><h2>Hungry<br><em>for a change?</em></h2><a class="btn" href="/menu" data-route>Plan your feast </a><p>Good company deserves good food.</p></div><span class="final-dish" aria-hidden="true"><svg class="food-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 23a12 12 0 0 1 24 0M2 23h28M5 27h22M16 11V8M13 8h6"/></svg></span></section></div>`}
function lunchMenu(){return `<div class="wrap lunch-builder">${crumbs('lunch')}<div class="pagehead"><div class="eyebrow">ONE MENU. YOUR PERFECT MIX.</div><h1>Let's put lunch together.</h1><p>Tell us what you have in mind. Choose your favourites and quantities, then add the details for your team lunch.</p></div><div class="menu-layout"><div><div class="products">${products.map(p=>`<article class="product"><div class="product-art">${art(p.id)}</div><div class="product-body"><h3 style="margin-top:10px">${p.label}</h3><p>${p.description}</p><div class="price">${money(p.price)} <small>/ ${p.unit}</small></div><div class="qty"><button data-qty="${p.id}" data-delta="-1" aria-label="Remove one ${p.label}">−</button><input id="qty-${p.id}" type="number" inputmode="numeric" min="0" max="200" step="1" value="${esc(draft.qty[p.id])}" data-quantity="${p.id}" aria-label="${p.label} quantity" aria-describedby="qerr-${p.id}"><button data-qty="${p.id}" data-delta="1" aria-label="Add one ${p.label}">+</button></div><span class="err" id="qerr-${p.id}">${esc(qtyErrors[p.id]||'')}</span></div></article>`).join('')}</div><div class="callout"><strong>A note on dietary requirements</strong>Use the next step to flag a discussion. Staff must assess suitability; no allergen-free or cross-contact assurances are made here.</div></div><div id="summary">${summary(undefined,'<button class="btn" id="menu-next">Review your request </button>')}<div id="menu-error" class="err" role="alert"></div></div></div></div>`}
function field(key,label,type='text',extra='',help=''){return `<div class="field ${extra.includes('full')?'full':''}"><label for="${key}">${label}</label><input id="${key}" name="${key}" type="${type}" value="${esc(draft[key])}" ${extra.replace('full','')} aria-describedby="err-${key}"><span id="err-${key}" class="err"></span>${help?`<span class="help">${help}</span>`:''}</div>`}
function dataNotice(){return ''}
function requestPage(){return `<div class="wrap">${crumbs('request')}<div class="pagehead"><div class="eyebrow">A FEW DETAILS FOR THE TEAM</div><h1>Set the scene.</h1><p>Tell us when and where you need lunch. The team will need to check availability for your requested date and time.</p></div>${dataNotice()}<div id="errors"></div><form id="request-form" novalidate><div class="form-layout"><div><section class="panel"><h2>01. The event</h2><div class="fields">${field('date','Requested date *','date')}${field('time','Requested time *','time','','Australia/Sydney timezone')}${field('headcount','Headcount (optional)','number','min="1" max="200" step="1"')}${field('company','Company (optional)','text','maxlength="100"')}</div><div id="mismatch" class="help"></div></section><section class="panel"><h2>02. Your contact details</h2><div class="fields">${field('name','Contact name *','text','maxlength="80"')}${field('email','Email address *','email','maxlength="254"')}${field('phone','Phone number (optional)','tel','maxlength="30" full')}</div></section><section class="panel"><h2>03. Delivery details</h2><div class="fields">${field('street','Street address *','text','maxlength="150" full')}${field('suburb','Suburb *','text','maxlength="100"')}${field('postcode','Postcode *','text','inputmode="numeric" maxlength="4"')}</div><p class="help">Delivery boundaries, eligibility and fees require staff review.</p></section><section class="panel"><h2>04. Dietary discussion</h2><fieldset style="border:0;padding:0;margin:0"><legend>Flag a discussion (optional)</legend>${['Vegetarian discussion','Vegan discussion','Other dietary discussion'].map((c,i)=>`<div class="checkline"><input id="cat-${i}" type="checkbox" data-category="${c}" ${draft.categories.includes(c)?'checked':''}><label for="cat-${i}">${c}</label></div>`).join('')}</fieldset><div class="field"><label for="note">Dietary discussion note (optional)</label><textarea id="note" name="note" maxlength="500" rows="3">${esc(draft.note)}</textarea><span class="help">Up to 500 characters. No attendee names or health records. Staff must discuss suitability and cross-contact.</span></div></section><div class="formactions"><a class="btn ghost" href="/lunch" data-route> Back to menu</a><button class="btn" type="submit">Review your request </button></div></div>${summary()}</div></form></div>`}
function detail(r){return `<div class="detailgrid"><p><small>Requested event</small>${esc(r.date)} at ${esc(r.time)}<br>Australia/Sydney · availability unconfirmed<br>${esc(r.headcount||'Not specified')} people · ${esc(r.company||'No company')}</p><p><small>Contact details</small>${esc(r.name)}<br>${esc(r.email)}<br>${esc(r.phone||'No phone entered')}</p><p><small>Delivery details</small>${esc(r.street||'Street address missing')}<br>${esc(r.suburb)}, ${esc(r.postcode)}<br>Delivery eligibility and fees unconfirmed</p><p><small>Dietary discussion</small>${esc(r.categories.length?r.categories.join(', '):'No category selected')}<br>${esc(r.note||'No discussion note entered.')}<br>Staff discussion required where relevant.</p></div>`}
function review(){return `<div class="wrap">${crumbs('review')}<div class="pagehead"><div class="eyebrow">ONE LAST LOOK</div><h1>A request, ready for review.</h1><p>Check your menu, quantities and event details before preparing your request for the catering team.</p></div>${dataNotice()}<div id="errors"></div><div class="form-layout"><div><section class="panel"><div class="stafftop"><h2>Your event brief</h2><a href="/request" data-route>Edit details</a></div>${detail(draft)}</section><div class="callout"><strong>Still to be checked by staff</strong>Availability, menu details, dietary suitability, delivery arrangements, tax, fees and final pricing. The catering team must confirm these details before accepting an order.</div><form id="simulate-form" style="margin-top:24px"><div class="checkline"><input id="ack" type="checkbox" ${draft.ack?'checked':''}><label for="ack">I have checked the event details and understand that availability and final pricing need team approval.</label></div><div class="formactions"><a class="btn ghost" href="/request" data-route> Back to details</a><button class="btn accent" id="simulate" ${busy?'disabled':''}>${busy?'Preparing…':'Prepare request '}</button></div></form></div>${summary()}</div></div>`}
function resultPage(){return `<div class="wrap"><div class="result"><div class="resultmark">${result?.failed?'↻':'✓'}</div><div class="eyebrow" style="justify-content:center">${result?.failed?'PLEASE TRY AGAIN':esc(result?.id||'REQUEST')}</div><h1 style="font-size:48px">${result?.failed?'Let’s try that again.':'Your request<br>is ready to review.'}</h1><p class="lead" style="margin:0 auto 25px">${result?.failed?'We couldn’t prepare your request. Your details are still here, ready for another try.':'Your lunch brief is prepared. Share it with the catering team to check availability, delivery and final pricing.'}</p>${result?.failed?'':readyBrief()}<div class="formactions">${result?.failed?'<a class="btn accent" href="/review" data-route>Try again </a>':'<a class="btn accent" href="/staff" data-route>View request details </a>'}<a class="btn ghost" href="/menu" data-route>Back to menu</a></div><p class="micro" style="margin-top:22px">Availability and pricing must be confirmed before an order is accepted.</p></div></div>`}
function staff(){let list=requests.filter(r=>filter==='All'||r.status===filter).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let r=requests.find(x=>x.id===selected)||requests[0];return `<div class="wrap"><div class="stafftop"><div class="pagehead"><div class="eyebrow">CATERING WORKSPACE</div><h1>The lunch desk.</h1><p>Review event details, clarify requirements and keep every lunch request moving.</p></div><button class="btn ghost" data-reset> Reset workspace</button></div><div class="staffgrid"><aside><label for="filter">Filter requests</label><select id="filter">${['All',...statuses].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><p class="help">${list.length} requests · sorted by requested date</p>${list.length?list.map(x=>`<button class="requestcard ${x.id===r.id?'selected':''}" data-select="${x.id}"><span class="tinytitle">${x.id}</span><strong>${esc(x.company||'Team lunch')}</strong><p>${esc(x.date)} · ${esc(x.time)} Sydney</p><span class="badge">${esc(x.status==='New'?'New · Unreviewed':x.status)}</span>${x.missing.length?'<p>⚑ Missing delivery information</p>':''}${x.categories.length?'<p>⚑ Dietary discussion required</p>':''}</button>`).join(''):'<div class="callout">No requests in this status.</div>'}</aside><div class="staff-detail"><section class="panel"><div class="stafftop"><div><span class="tinytitle">${r.id} / LUNCH REQUEST</span><h2 style="margin:12px 0">${esc(r.company||'Team lunch')}</h2></div><span class="badge">${esc(r.status)}</span></div>${r.missing.length?`<div class="callout" style="margin:15px 0"><strong>Needs clarification</strong>${r.missing.map(esc).join(', ')}. Identify the missing detail before quoting.</div>`:''}${r.categories.length?'<div class="callout" style="margin:15px 0"><strong>Dietary discussion required</strong>Staff must discuss suitability. This flag does not resolve dietary safety.</div>':''}${detail(r)}<div style="margin-top:20px">${products.filter(p=>r.qty[p.id]>0).map(p=>`<div class="summaryline"><span>${r.qty[p.id]} × ${p.label}</span><span>${money(r.qty[p.id]*p.price)}</span></div>`).join('')}<div class="summaryline total"><span>Menu subtotal</span><span>${money(totals(r.qty).sum)}</span></div><p class="micro">Final pricing, delivery and any additional charges require review.</p></div></section><section class="panel"><h2>Review & next step</h2><form id="staff-form"><div class="fields"><div class="field"><label for="status">Review status</label><select id="status">${statuses.map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="reason">Internal reason / review note</label><input id="reason" maxlength="300" placeholder="Add a review note"></div></div><div class="field" style="margin-top:18px"><label for="staffNote">Internal team note</label><textarea id="staffNote" maxlength="500" rows="3">${esc(r.staffNote)}</textarea><p class="help">Record questions, decisions and anything the team needs to check.</p></div><button class="btn" type="submit">Save review</button><p id="saved" class="successnote" role="status"></p></form><h3 style="font-size:22px;margin-top:20px">Status history</h3>${r.history.length?r.history.map(h=>`<div class="history">${esc(h.from)} → ${esc(h.to)}<br><span class="micro">${esc(h.at)} · Team member</span><br>${esc(h.reason)}</div>`).join(''):'<p class="micro">No status changes yet.</p>'}</section></div></div></div>`}
function navigate(path){history.pushState({},'',path);render();let anchor=location.hash.slice(1);if(anchor&&document.getElementById(anchor)){document.getElementById(anchor).scrollIntoView()}else{window.scrollTo({top:0,behavior:'instant'})}}
function render(){let path=location.pathname.replace(/^\/demo(?=\/|$)/,'').replace(/\/$/,'');document.body.classList.remove('mobile-nav-open');document.body.classList.toggle('is-home',path==='');resetHeader();document.querySelectorAll('header details').forEach(x=>x.open=false);app.innerHTML=path==='/how-it-works'?howPage():path==='/menu'?menu():path==='/lunch'?lunchMenu():path.startsWith('/menus/')?collectionPage(path.split('/')[2]):path==='/about'?aboutPage():path==='/functions'?functionsPage():path==='/weddings'?weddingsPage():path==='/contact'?contactPage():path==='/request'?requestPage():path==='/review'?review():path==='/result'?resultPage():path==='/staff'?staff():landing();document.title=(path==='/menu'?'Menus':path==='/lunch'?'Lunch request':path.startsWith('/menus/')?(collectionData.find(c=>c.id===path.split('/')[2])?.title||'Menus'):path==='/about'?'About Tracy & the team':path==='/functions'?'Functions & events':path==='/weddings'?'Weddings':path==='/contact'?'Contact Tracy':path==='/staff'?'Catering workspace':path==='/request'?'Event details':path==='/review'?'Review your request':'Newcastle & Hunter catering')+' · Feast Catering';if(path==='/request')mismatch();observeReveals();initWow();syncPlanner()}
function announce(t){document.querySelector('#live').textContent=t}
function validQuantities(){return products.every(p=>Number.isInteger(Number(draft.qty[p.id]))&&Number(draft.qty[p.id])>=0&&Number(draft.qty[p.id])<=200)&&!Object.keys(qtyErrors).length}
function errors(){let e=[];if(!validQuantities()||!totals().count)e.push(['date','Add at least one item with valid whole-number quantities (0–200).']);let dateStr=draft.date+'T'+draft.time+':00';let sydneyNow=new Date().toLocaleString('sv-SE',{timeZone:'Australia/Sydney'}).replace(' ','T');if(!draft.date||!draft.time||dateStr<=sydneyNow)e.push(['date','Choose a future requested date and time in Australia/Sydney.']);if(draft.headcount&&(!Number.isInteger(Number(draft.headcount))||draft.headcount<1||draft.headcount>200))e.push(['headcount','Enter a whole-number headcount from 1 to 200.']);for(let [k,l,max] of [['name','contact name',80],['street','street address',150],['suburb','suburb',100]])if(!draft[k].trim()||draft[k].length>max)e.push([k,`Enter a ${l} (up to ${max} characters).`]);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email))e.push(['email','Enter a valid email address.']);if(!/^\d{4}$/.test(draft.postcode))e.push(['postcode','Enter a four-digit postcode.']);if(draft.company.length>100)e.push(['company','Use up to 100 characters.']);if(draft.phone.length>30)e.push(['phone','Use up to 30 characters.']);if(draft.note.length>500)e.push(['note','Use up to 500 characters.']);return e}
function showErrors(e){let el=document.querySelector('#errors');el.innerHTML=`<div class="errors" tabindex="-1" id="error-summary"><strong>Please check these details</strong>${e.map(([k,t])=>`<a href="#${k}" data-error-focus="${k}">${esc(t)}</a>`).join('')}</div>`;for(let[k,t]of e){let input=document.getElementById(k);if(input)input.setAttribute('aria-invalid','true');let n=document.getElementById('err-'+k);if(n)n.textContent=t}document.querySelector('#error-summary').focus()}
function mismatch(){let el=document.querySelector('#mismatch');if(el)el.textContent=draft.headcount&&Number(draft.headcount)!==totals().count?`Heads-up: ${draft.headcount} people and ${totals().count} items. Staff would clarify portions; you can still continue.`:''}
function updateQuantity(id,value){if(value===''||!Number.isInteger(Number(value))||Number(value)<0||Number(value)>200){qtyErrors[id]='Use a whole number from 0 to 200.'}else{delete qtyErrors[id];draft.qty[id]=Number(value)}let err=document.querySelector('#qerr-'+id);if(err)err.textContent=qtyErrors[id]||'';document.querySelector('#summary').innerHTML=summary(undefined,'<button class="btn" id="menu-next">Review your request </button>')+'<div id="menu-error" class="err" role="alert"></div>';syncPlanner();announce(`${totals().count} items. Menu subtotal ${money(totals().sum)}.`)}
document.addEventListener('click',e=>{let a=e.target.closest('[data-route]');if(a){if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.hasAttribute('download')||(a.target&&a.target!=='_self'))return;let url=new URL(a.href,location.href);if(url.origin!==location.origin)return;e.preventDefault();navigate(url.pathname+url.search+url.hash);return}if(e.target.closest('[data-how]')){e.preventDefault();navigate('/#how');document.querySelector('#how')?.scrollIntoView();return}let f=e.target.closest('[data-error-focus]');if(f){e.preventDefault();document.getElementById(f.dataset.errorFocus)?.focus();return}let b=e.target.closest('[data-qty]');if(b){let id=b.dataset.qty;let v=Math.max(0,Math.min(200,(Number(draft.qty[id])||0)+Number(b.dataset.delta)));document.querySelector('#qty-'+id).value=v;updateQuantity(id,v)}if(e.target.closest('#menu-next')){if(!validQuantities()||!totals().count){document.querySelector('#menu-error').textContent='Add at least one item and use whole-number quantities from 0 to 200.';return}navigate('/request')}if(e.target.closest('#reset,[data-reset]')){reset();render();announce('Workspace reset.')}let r=e.target.closest('[data-select]');if(r){selected=r.dataset.select;render()}});
document.addEventListener('input',e=>{let t=e.target;if(t.dataset.quantity)updateQuantity(t.dataset.quantity,t.value);else if(t.closest('#request-form')&&t.name){draft[t.name]=t.value;mismatch()}else if(t.id==='ack')draft.ack=t.checked});
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.category){draft.categories=[...document.querySelectorAll('[data-category]:checked')].map(x=>x.dataset.category)}if(t.id==='filter'){filter=t.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='request-form'){let er=errors();if(er.length){showErrors(er);return}navigate('/review')}else if(e.target.id==='simulate-form'){if(busy)return;let er=errors();if(!draft.ack)er.push(['ack','Please confirm that you have checked the event details.']);if(er.length){showErrors(er);return}let fail=false;let run=++simulationRun;busy=true;let btn=document.querySelector('#simulate');btn.disabled=true;btn.textContent='Preparing…';announce('Preparing your lunch request.');setTimeout(()=>{if(run!==simulationRun)return;busy=false;if(fail){result={failed:true}}else{let id='REQ-'+String(requests.length+1).padStart(3,'0');requests.push({id,...structuredClone(draft),status:'New',missing:[],history:[],staffNote:''});selected=id;filter='All';result={id}}navigate('/result');let h=app.querySelector('h1');h.tabIndex=-1;h.focus();announce(fail?'Request preparation failed. Your details are preserved.':'Your lunch brief is prepared. Share it with the catering team to check availability, delivery and final pricing.')},700)}else if(e.target.id==='staff-form'){let r=requests.find(x=>x.id===selected);let to=document.querySelector('#status').value;let reason=document.querySelector('#reason').value.trim();if(to==='Closed'&&!reason){document.querySelector('#reason').setCustomValidity('Add an internal reason to close this request.');document.querySelector('#reason').reportValidity();document.querySelector('#reason').oninput=()=>document.querySelector('#reason').setCustomValidity('');return}r.staffNote=document.querySelector('#staffNote').value;if(to!==r.status){r.history.unshift({from:r.status,to,reason,at:new Date().toLocaleString('en-AU',{timeZone:'Australia/Sydney'})});r.status=to}render();document.querySelector('#saved').textContent='Review updated.'}});
window.addEventListener('popstate',render);buildNav();render();

function observeReveals(){if(!('IntersectionObserver' in window))return;const io=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');io.unobserve(e.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>io.observe(el))}

document.addEventListener('click',e=>{if(e.target.closest('[data-food-scroll]')){e.preventDefault();document.querySelector('#food-menu')?.scrollIntoView({behavior:document.body.classList.contains('motion-paused')?'instant':'smooth'})}let motion=e.target.closest('#motion-toggle');if(motion){const paused=document.body.classList.toggle('motion-paused');motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Play motion':'Pause motion'}});

document.addEventListener('click',e=>{let toggle=e.target.closest('#nav-toggle');if(toggle){let open=document.body.classList.toggle('mobile-nav-open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')}let f=e.target.closest('[data-collection-filter]');if(f){activeCollectionFilter=f.dataset.collectionFilter;let y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});announce('Showing '+(activeCollectionFilter==='all'?'all menus':activeCollectionFilter==='delivery'?'delivered menus':activeCollectionFilter==='venue'?'venue menus':'private dining menus'))}if(e.target.closest('#copy-enquiry')){let text=document.querySelector('#enquiry-copy').value;navigator.clipboard.writeText(text).then(()=>document.querySelector('#copy-status').textContent='Copied. Paste this into your email to Tracy.').catch(()=>document.querySelector('#copy-status').textContent='Select and copy the enquiry text below.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('header details').forEach(x=>x.open=false);document.body.classList.remove('mobile-nav-open');resetHeader()}});
document.addEventListener('submit',e=>{if(e.target.id!=='enquiry-form')return;e.preventDefault();const data=new FormData(e.target);let content='Catering enquiry for Tracy Roddenby\n\n'+[...data.entries()].filter(([k,v])=>v).map(([k,v])=>k.charAt(0).toUpperCase()+k.slice(1)+': '+v).join('\n');document.querySelector('#enquiry-result').innerHTML='<div class="callout"><h3>Your enquiry is prepared.</h3><p>Copy your summary and email it to tracy@feastcateringnewcastle.com.au to discuss your plans.</p><label for="enquiry-copy">Your enquiry summary</label><textarea id="enquiry-copy" rows="10" readonly>'+esc(content)+'</textarea><button type="button" class="btn" id="copy-enquiry">Copy enquiry</button><p id="copy-status" role="status"></p></div>';document.querySelector('#enquiry-result').scrollIntoView({block:'center'})});

document.addEventListener("toggle",e=>{if(e.target.matches("header details")&&e.target.open){document.querySelectorAll("header details").forEach(x=>{if(x!==e.target)x.open=false})}},true);
